import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"Docker 部署","description":"","frontmatter":{},"headers":[],"relativePath":"operations/deployment.md","filePath":"operations/deployment.md","lastUpdated":0}`),a={name:`operations/deployment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to “Docker 部署”">​</a></h1><p>本文面向自行部署草丛 Mail 的运维人员。生产源码仓库保持私有；本公开仓库只保存文档，不提供完整应用源码。</p><h2 id="服务组成" tabindex="-1">服务组成 <a class="header-anchor" href="#服务组成" aria-label="Permalink to “服务组成”">​</a></h2><p>标准部署由以下容器组成：</p><table tabindex="0"><thead><tr><th>服务</th><th>用途</th></tr></thead><tbody><tr><td><code>db</code></td><td>PostgreSQL 业务数据</td></tr><tr><td><code>redis</code></td><td>缓存、会话或队列辅助</td></tr><tr><td><code>rspamd</code></td><td>反垃圾与隔离处理</td></tr><tr><td><code>backend</code></td><td>Web API、SMTP、IMAP 和 POP3 服务</td></tr><tr><td><code>frontend</code></td><td><code>/app/</code> 邮箱应用静态站点</td></tr><tr><td><code>website</code></td><td>产品官网静态站点</td></tr><tr><td><code>nginx</code></td><td>同域路由与静态资源入口</td></tr></tbody></table><p>公网 HTTPS 可由宿主机面板或独立反向代理终止，再转发到 Docker Web 入口。邮件端口直接映射时应配置主机防火墙。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to “前置条件”">​</a></h2><ul><li>支持 Docker Compose 的 Linux 主机。</li><li>可控域名和 DNS，能够设置 A、MX、TXT 记录。</li><li>开放 Web、SMTP Submission、IMAPS 和 POP3S 所需端口。</li><li>为 PostgreSQL 数据卷准备持久化磁盘和备份空间。</li></ul><h2 id="配置原则" tabindex="-1">配置原则 <a class="header-anchor" href="#配置原则" aria-label="Permalink to “配置原则”">​</a></h2><p>以私有源码仓库提供的示例环境文件为起点，生成全新的数据库密码、JWT 密钥和各外部服务密钥。不要直接使用示例值，也不要提交真实 <code>.env</code>。</p><p>公开 URL、邮件主机名和应用路径要保持一致。草丛 Mail 当前网站使用根路径，邮箱应用使用 <code>/app/</code>；反向代理应保留旧入口重定向。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to “首次启动”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>后端启动时会按顺序执行数据库迁移。迁移失败时不要反复重启或手工标记成功，应先根据日志修复具体问题。</p><h2 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to “DNS”">​</a></h2><p>至少配置：</p><ul><li>Web 与邮件主机的 A/AAAA 记录。</li><li>指向邮件主机的 MX 记录。</li><li>授权实际发信源的 SPF。</li><li>与后台当前选择器、公钥一致的 DKIM。</li><li>从观察策略开始并逐步收紧的 DMARC。</li></ul><p>反向 DNS 通常由服务器提供商配置，应与邮件主机名匹配。</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>网页与邮件协议都必须使用有效证书。邮件服务需要能够读取证书链和私钥；文件更新后重启或重载后端，并分别验证 587 STARTTLS、993 和 995 实际提供的新证书。</p><p>自动续期脚本应只允许 root 读取，并在续期后同步应用配置和重载服务。不要把私钥复制到仓库或容器镜像。</p><h2 id="上线前" tabindex="-1">上线前 <a class="header-anchor" href="#上线前" aria-label="Permalink to “上线前”">​</a></h2><p>完成<a href="/nodemail-docs/operations/verification">上线检查记录</a>中的检查，并建立数据库和持久化数据的异机备份。首次上线建议用专用测试账号验证注册、收信、发信、附件、密码找回和管理员流程。</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};